const payload = $input.first().json;
const portfolioEquity = payload.portfolioEquity || 100000;
const requestedSize = payload.requestedSizeUsd || 8000;
const currentDailyDrawdown = payload.dailyDrawdownPercent || 0.8;
const winRate = payload.winRate || 0.58;
const rrRatio = payload.rrRatio || 2.2;

// Kelly Criterion: f* = (p*b - q)/b
const p = winRate;
const q = 1 - p;
const b = rrRatio;
const fullKelly = (p * b - q) / b;
const safeKellyFraction = Math.max(0, fullKelly) * 0.25;
const recommendedKellyUsd = Math.round(portfolioEquity * safeKellyFraction);

// VaR 99% 1-day check
const var99Usd = Math.round(portfolioEquity * 0.025 * 2.326);
const circuitBreaker = currentDailyDrawdown >= 3.0;
const approved = !circuitBreaker && requestedSize <= (recommendedKellyUsd * 1.5);
const approvedSize = circuitBreaker ? 0 : Math.min(requestedSize, recommendedKellyUsd);

return {
  json: {
    portfolioEquity,
    requestedSize,
    approvedSize,
    safeKellyFractionPercent: Math.round(safeKellyFraction * 1000) / 10,
    var99Usd,
    currentDailyDrawdown,
    circuitBreakerTriggered: circuitBreaker,
    approved,
    verdict: approved ? 'RISK_APPROVED' : circuitBreaker ? 'CIRCUIT_BREAKER_HALT' : 'SIZE_SCALED_DOWN'
  }
};

const prev = $input.first().json;
const text = prev.content || prev.output || JSON.stringify(prev);

return {
  json: {
    success: true,
    botId: 'risk-sentinel',
    botName: 'Portfolio Risk Sentinel & Drawdown Coordinator',
    riskCertificate: text,
    clearanceTimestamp: new Date().toISOString()
  }
};
